import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"Verification status","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/kits/verification.md","filePath":"en/modules/kits/verification.md","lastUpdated":0}`),a={name:`en/modules/kits/verification.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="verification-status" tabindex="-1">Verification status <a class="header-anchor" href="#verification-status" aria-label="Permalink to “Verification status”">​</a></h1><p>This page records the verification progress of EmakiKits 1.0.6 honestly: verified tiers and the pending live-test checklist are listed separately, and static checks never stand in for live results</p><h2 id="verified" tabindex="-1">Verified <a class="header-anchor" href="#verified" aria-label="Permalink to “Verified”">​</a></h2><table tabindex="0"><thead><tr><th>Tier</th><th>Result</th></tr></thead><tbody><tr><td>Compile / build</td><td>Full build BUILD SUCCESSFUL this round (GraalVM JDK 25, the repository&#39;s own gradlew)</td></tr></tbody></table><p>The repository has no unit-test infrastructure, so the only verification tiers are compile / build and live server</p><h2 id="pending-live-tests-paper-26-1-26-2-26-3-folia-4x-matrix" tabindex="-1">Pending live tests (Paper 26.1 / 26.2 / 26.3 + Folia, 4x matrix) <a class="header-anchor" href="#pending-live-tests-paper-26-1-26-2-26-3-folia-4x-matrix" aria-label="Permalink to “Pending live tests (Paper 26.1 / 26.2 / 26.3 + Folia, 4x matrix)”">​</a></h2><p>The four-environment matrix run has <strong>not been executed yet</strong>, waiting for a live-server window. Every environment must cover the scenarios below; all of them are currently pending:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Coverage</th></tr></thead><tbody><tr><td>Eight kit types</td><td>One claim each of <code>join</code> / <code>invite</code> / <code>daily</code> / <code>weekly</code> / <code>monthly</code> / <code>cdk</code> / <code>choice</code> / <code>generic</code></td></tr><tr><td>CDK redemption</td><td><code>global_once</code> once server-wide; <code>per_player_once</code> counted by <code>cdk.per_player_limit</code> with rejection at the cap; failed deliveries roll back without counting</td></tr><tr><td>Invite binding</td><td>Successful bind; each (inviter, invitee) pair binds once; rejection at <code>invite.max_binds_per_invitee</code></td></tr><tr><td>Choice GUI</td><td>Open the inline GUI, <code>min_select</code> / <code>max_select</code> validation, option rewards granted</td></tr><tr><td>Purchase debit</td><td>Balance debited, <code>max_purchases</code> cap, rejection when the economy bridge is absent and price &gt; 0</td></tr><tr><td>reload</td><td>New configuration effective after <code>/ekits reload</code></td></tr><tr><td>Restart recovery</td><td>After a simulated power cut and restart, <code>data/store.yml</code> stays consistent and duplicate claims are rejected (see <a href="./reliability.html">Reliability</a>)</td></tr><tr><td>Three switches</td><td>Effective values of <code>cdk.per_player_limit</code> / <code>invite.max_binds_per_invitee</code> / <code>cycle.allow_makeup</code> match <code>/ekits check</code> output</td></tr><tr><td>Makeup claim</td><td><code>claim &lt;kit&gt; makeup</code> makes up the previous period once, a second attempt is rejected, the current period is unaffected</td></tr><tr><td>Pity</td><td><code>rewards.pity</code> forces the guaranteed entry on the N-th roll after N-1 misses, and resets after it drops</td></tr><tr><td>Leaderboard</td><td><code>/ekits top</code> GUI sorting and paging; <code>%emakikits_invited%</code> output matches the bind statistics</td></tr><tr><td>Editor</td><td><code>/ekits edit</code> create / edit / delete, effective after save + reload, failed validation never writes</td></tr><tr><td>Diagnostics</td><td><code>/ekits check</code> output matches the actual configuration</td></tr><tr><td>Offline audit</td><td><code>/ekits inspect &lt;player or UUID&gt;</code> queries offline player records</td></tr></tbody></table><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to “Rules”">​</a></h2><ul><li>Pending items must never be presented as verified in any public copy (see <a href="./promotion.html">Promotion</a>)</li><li>This page is updated as live tests land; each item becomes pass / fail with log evidence</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};